'use strict';

// MODULES //

var isEvenf = require( '@stdlib/math/base/assert/is-evenf' );
var float64ToFloat32 = require( '@stdlib/number/float64/base/to-float32' );
var MAX_SAFE_INTEGER = require( '@stdlib/constants/float32/max-safe-integer' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var NINF = require( '@stdlib/constants/float32/ninf' );


// MAIN //

/**
* Tests if a finite single-precision floating-point number is an odd number.
*
* @param {number} x - value to test
* @returns {boolean} boolean indicating whether the value is an odd number
*
* @example
* var bool = isOddf( 5.0 );
* // returns true
*
* @example
* var bool = isOddf( -2.0 );
* // returns false
*
* @example
* var bool = isOddf( 0.0 );
* // returns false
*
* @example
* var bool = isOddf( NaN );
* // returns false
*/
function isOddf( x ) {
	x = float64ToFloat32( x );

	// Every finite value whose magnitude exceeds the maximum safe integer is even, but `x-1` and `x+1` would round to an even value...
	if ( x > MAX_SAFE_INTEGER ) {
		return ( x === PINF );
	}
	if ( x < -MAX_SAFE_INTEGER ) {
		return ( x === NINF );
	}
	// Check sign to prevent overflow...
	if ( x > 0.0 ) {
		return isEvenf( float64ToFloat32( x - 1.0 ) );
	}
	return isEvenf( float64ToFloat32( x + 1.0 ) );
}


// EXPORTS //

module.exports = isOddf;
